const localLabel = localState === 'ready' ? '进入' : localState === 'starting' ? '本地服务启动中…' : '本地服务';

// shell (v3.6): 一键进服消费端 —— 服务器面板选中后 window.shell.setAutostart() 布防（随后切服重载），
// 标题页初始化在此取用一次：takeAutostart() === '1' 时等 400ms（等代号预填与 socket 就绪）
// 自动走既有 start()；取用即清除（Java 侧 commit），无名/桥缺失静默回退手动。
useEffect(() => {
  let armed = false;
  try {
    armed = !!(window.shell && typeof window.shell.takeAutostart === 'function'
      && String(window.shell.takeAutostart()) === '1');
  } catch (e) { armed = false; }
  if (!armed) return undefined;
  const timer = setTimeout(() => {
    try { if (isValidName(name)) start(); } catch (e) { /* 手动回退 */ }
  }, 400);
  return () => clearTimeout(timer);
}, []);

/* v3.6: 首页双按钮并排 —— 本地服务 | 线上服务，同一行各占一半（等宽；半宽下收紧字号/字距） */
.title-login .title-duo { display: flex; align-items: stretch; gap: .12rem; }
.title-login .title-duo > .btn { flex: 1 1 0; min-width: 0; font-size: .22rem; letter-spacing: .06em; padding-left: .1rem; padding-right: .08rem; }
.title-login .title-duo .btn__label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* v3.6: 本地服务「启动中…」文案最长（8 字），半宽下再收紧一点，避免溢出 */
.title-login .btn--xl.title-local { letter-spacing: 0; padding-left: .06rem; padding-right: .06rem; }

.set-hint kbd, .lvcard__key, .toolbtn kbd { font-family: var(--font-num); font-size: .11rem; border: 1px solid var(--line-2); padding: 0 .04rem; color: var(--text-lo); background: rgba(0, 0, 0, .3); }
/* shell (v3.6): 服务器面板统一列表 —— 两列等宽网格（窄屏回退单列），单行格：名称 · v版本 · 延迟色阶 */
.sp-srv-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .1rem; }
.sp-srv-cell { display: flex; align-items: center; min-width: 0; height: .56rem; background: rgba(8, 11, 10, .55); border: 1px solid var(--line-2); border-radius: .04rem; overflow: hidden; }
.sp-srv-cell.is-cur { border-color: var(--mint-500); box-shadow: inset 0 0 0 1px rgba(23, 249, 183, .22); }
.sp-srv-cell.is-off { opacity: .45; }
.sp-srv-main { display: flex; align-items: center; gap: .08rem; flex: 1 1 auto; min-width: 0; height: 100%; padding: 0 .1rem 0 .12rem; background: transparent; border: 0; color: var(--text-hi, #f2f2f2); font-size: .16rem; cursor: pointer; text-align: left; }
.sp-srv-main:disabled { cursor: not-allowed; }
.sp-srv-name { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sp-srv-ver { flex: 0 0 auto; font-size: .14rem; color: var(--text-lo, #8a948f); white-space: nowrap; }
.sp-srv-rtt { flex: 0 0 auto; font-size: .14rem; font-variant-numeric: tabular-nums; white-space: nowrap; }
.sp-srv-cur { flex: 0 0 auto; width: .08rem; height: .08rem; border-radius: 50%; background: var(--mint-500); box-shadow: 0 0 .08rem rgba(23, 249, 183, .8); }
.sp-srv-alt { flex: 0 0 auto; display: grid; place-items: center; width: .36rem; height: 100%; background: transparent; border: 0; border-left: 1px solid var(--line-2); color: var(--text-lo, #8a948f); cursor: pointer; }
.sp-srv-alt.is-on { color: var(--mint-400, #4ed8af); background: rgba(78, 216, 175, .12); }
@media (max-width: 600px) { .sp-srv-grid { grid-template-columns: 1fr; } }
